using System;using System.IO;using System.Collections.Generic;using CaeMesh;using CaeModel;using PrePoMax;
class StrictFixtureTests {
 static int checks;static void Check(bool b,string s){if(!b)throw new Exception(s);checks++;}
 static FeModel Box(double length=100){var m=new FeModel("Explicit_B01_Test");double[,] p={{0,0,0},{length,0,0},{length,10,0},{0,10,0},{0,0,10},{length,0,10},{length,10,10},{0,10,10}};var n=new Dictionary<int,FeNode>();for(int i=0;i<8;i++)n.Add(i+1,new FeNode(i+1,p[i,0],p[i,1],p[i,2]));int[][] conn={new[]{1,2,3,7},new[]{1,3,4,7},new[]{1,4,8,7},new[]{1,8,5,7},new[]{1,5,6,7},new[]{1,6,2,7}};var e=new Dictionary<int,FeElement>();for(int i=0;i<6;i++)e.Add(i+1,new LinearTetraElement(i+1,conn[i]));m.SetMesh(new FeMesh(n,e,MeshRepresentation.Mesh));return m;}
 static int Main(string[] args){try{var m=Box();string before=AsterMaxStrictNativeFixture.MeshHash(m);var r=AsterMaxStrictNativeFixture.Configure(m);Check(before==AsterMaxStrictNativeFixture.MeshHash(m),"mesh unchanged");Check(!(bool)r["mesh_replaced"],"not synthetic replacement");Check((int)r["fixed_nodes"]==4&&(int)r["loaded_nodes"]==4,"end faces");var c=AsterMaxModelContractBridge.Build(m);var force=AsterMaxForceDistribution.Build(c);Check((double)r["force_per_node_x_n"]*4==10000,"explicit total preserved");AsterMaxCodeAsterNativeExporter.ExportContract(c,args[0],"b01");Check(File.ReadAllText(Path.Combine(args[0],"b01.comm")).Contains("MECA_STATIQUE"),"actual exporter");var wrong=Box(99);string wrongHash=AsterMaxStrictNativeFixture.MeshHash(wrong);bool rejected=false;try{AsterMaxStrictNativeFixture.Configure(wrong);}catch(InvalidOperationException){rejected=true;}Check(rejected&&AsterMaxStrictNativeFixture.MeshHash(wrong)==wrongHash&&wrong.Materials.Count==0,"wrong geometry rejected without mutation");Console.WriteLine("PASS "+checks+" checks; synthetic managed TETRA4, not NetGen or Windows.");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
